start_node = "8f14e45fce"

queue = deque([(start_node, 0)])
visited = {start_node}
depth_map = {start_node: 0}

while queue:
    node, depth = queue.popleft()

    for neighbor in adj[node]:
        if neighbor not in visited:
            visited.add(neighbor)
            depth_map[neighbor] = depth + 1
            queue.append((neighbor, depth + 1))

print("Depth map for all reachable nodes:")
for node, d in sorted(depth_map.items(), key=lambda x: (x[1], x[0])):
    print(f"  {node}: depth {d}")

print(f"\nNodes at exactly depth 4:")
depth_4_nodes = [node for node, d in depth_map.items() if d == 4]
print(sorted(depth_4_nodes))
